package cloudrun

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"

	"go.temporal.io/sdk/client"
	"go.temporal.io/sdk/worker"
	"go.temporal.io/sdk/workflow"
)

const (
	// defaultMetadataURL is the GCP metadata server endpoint that returns the unique,
	// autogenerated numeric ID of the current Cloud Run instance. The instance ID is only
	// available from the metadata server; unlike the name and revision, Cloud Run does not
	// expose it as an environment variable. The metadata server is available on both Cloud Run
	// worker pools and Cloud Run services.
	defaultMetadataURL = "http://metadata.google.internal/computeMetadata/v1/instance/id"

	// metadataFlavorHeader and metadataFlavorValue form the header the GCP metadata server
	// requires on every request as a guard against DNS-rebinding attacks.
	metadataFlavorHeader = "Metadata-Flavor"
	metadataFlavorValue  = "Google"

	// Cloud Run worker pools inject these environment variables into every container instance.
	// Worker pools do NOT receive any K_* variables.
	envWorkerPool         = "CLOUD_RUN_WORKER_POOL"
	envWorkerPoolRevision = "CLOUD_RUN_REVISION"

	// Cloud Run services inject these environment variables into every container instance.
	// Services do NOT receive any CLOUD_RUN_* variables.
	envService         = "K_SERVICE"
	envServiceRevision = "K_REVISION"

	// defaultHTTPTimeout bounds the metadata request. The metadata server is a link-local
	// endpoint, so a short timeout is appropriate.
	defaultHTTPTimeout = 2 * time.Second
)

// Metadata describes the Google Cloud Run instance that a worker process is running on, covering
// both Cloud Run worker pools and Cloud Run services. Use [FetchMetadata] to populate it at worker
// startup, then apply it to your client and worker options with [Metadata.ApplyToClientOptions] and
// [Metadata.ApplyToWorkerOptions] (or read [Metadata.WorkerIdentity] and
// [Metadata.DeploymentVersion] directly).
//
// Experimental: Google Cloud Run support is experimental and its API may change in a future
// release.
type Metadata struct {
	// InstanceID is the unique, autogenerated ID of the Cloud Run instance, read from the GCP
	// metadata server. It is empty only if the metadata request could not be made.
	InstanceID string

	// Name is the Temporal deployment name for this worker: the Cloud Run worker pool name (from
	// CLOUD_RUN_WORKER_POOL) or, on a Cloud Run service, the service name (from K_SERVICE).
	Name string

	// Revision is the name of the Cloud Run revision, read from CLOUD_RUN_REVISION (worker pools)
	// or K_REVISION (services). Cloud Run creates a new revision for each deployment, which makes
	// it a natural worker build ID.
	Revision string
}

// options holds the resolved configuration for [FetchMetadata].
type options struct {
	httpClient  *http.Client
	metadataURL string
}

// Option customizes the behavior of [FetchMetadata].
type Option func(*options)

// WithHTTPClient overrides the [http.Client] used to query the metadata server. It is primarily
// useful for setting a custom timeout or transport, or for testing. If nil or unset, a client with
// a default two-second timeout is used.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) {
		o.httpClient = c
	}
}

// WithMetadataURL overrides the metadata server URL used to fetch the instance ID. If unset, the
// standard Cloud Run endpoint is used. It is primarily useful for testing.
func WithMetadataURL(url string) Option {
	return func(o *options) {
		o.metadataURL = url
	}
}

// FetchMetadata reads the current Cloud Run instance's metadata. It reads the deployment name and
// revision from environment variables — CLOUD_RUN_WORKER_POOL and CLOUD_RUN_REVISION on Cloud Run
// worker pools, or K_SERVICE and K_REVISION on Cloud Run services — and fetches the unique instance
// ID from the GCP metadata server.
//
// FetchMetadata performs a network request and must be called at worker startup, never from
// workflow code: the SDK's workflowcheck analyzer flags net/http usage inside workflows because it
// is non-deterministic.
//
// The provided context bounds the metadata request. Configure the request further with
// [WithHTTPClient] and [WithMetadataURL].
//
// Experimental: Google Cloud Run support is experimental and its API may change in a future
// release.
func FetchMetadata(ctx context.Context, opts ...Option) (*Metadata, error) {
	o := options{
		httpClient:  &http.Client{Timeout: defaultHTTPTimeout},
		metadataURL: defaultMetadataURL,
	}
	for _, opt := range opts {
		opt(&o)
	}
	if o.httpClient == nil {
		o.httpClient = &http.Client{Timeout: defaultHTTPTimeout}
	}
	if o.metadataURL == "" {
		o.metadataURL = defaultMetadataURL
	}

	md := &Metadata{
		Name:     firstNonEmptyEnv(envWorkerPool, envService),
		Revision: firstNonEmptyEnv(envWorkerPoolRevision, envServiceRevision),
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, o.metadataURL, nil)
	if err != nil {
		return nil, fmt.Errorf("cloudrun: building metadata request: %w", err)
	}
	req.Header.Set(metadataFlavorHeader, metadataFlavorValue)

	resp, err := o.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("cloudrun: requesting instance ID from the metadata server "+
			"(is this process running on a Cloud Run worker pool or service?): %w", err)
	}
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("cloudrun: reading instance ID from the metadata server response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("cloudrun: metadata server returned status %d when requesting the "+
			"instance ID (is this process running on a Cloud Run worker pool or service?)", resp.StatusCode)
	}

	md.InstanceID = strings.TrimSpace(string(body))
	return md, nil
}

// firstNonEmptyEnv returns the value of the first environment variable in names that is set to a
// non-empty value, or the empty string if none are set.
func firstNonEmptyEnv(names ...string) string {
	for _, n := range names {
		if v := os.Getenv(n); v != "" {
			return v
		}
	}
	return ""
}

// WorkerIdentity returns a client identity string for the Cloud Run instance, in the form
// "<InstanceID>@<Revision>". If the revision is unknown it falls back to "<InstanceID>@<Name>", and
// if both are unknown it returns just the instance ID. Pass the result to
// [go.temporal.io/sdk/client.Options.Identity] when dialing the Temporal server, or use
// [Metadata.ApplyToClientOptions].
func (m *Metadata) WorkerIdentity() string {
	switch {
	case m.Revision != "":
		return fmt.Sprintf("%s@%s", m.InstanceID, m.Revision)
	case m.Name != "":
		return fmt.Sprintf("%s@%s", m.InstanceID, m.Name)
	default:
		return m.InstanceID
	}
}

// DeploymentVersion returns the [worker.WorkerDeploymentVersion] for the Cloud Run instance, using
// the name as the deployment name and the revision as the build ID. Set it on
// [go.temporal.io/sdk/worker.DeploymentOptions.Version] (with UseVersioning enabled) to opt the
// worker into Worker Deployment Versioning, or use [Metadata.ApplyToWorkerOptions].
//
// It returns an error if either the name or the revision is unknown, which typically means the
// process is not running on a Cloud Run worker pool or service.
func (m *Metadata) DeploymentVersion() (worker.WorkerDeploymentVersion, error) {
	if m.Name == "" || m.Revision == "" {
		return worker.WorkerDeploymentVersion{}, fmt.Errorf("cloudrun: cannot build a worker "+
			"deployment version: both the Cloud Run deployment name (%q, from CLOUD_RUN_WORKER_POOL "+
			"or K_SERVICE) and revision (%q, from CLOUD_RUN_REVISION or K_REVISION) must be set "+
			"(is this process running on a Cloud Run worker pool or service?)", m.Name, m.Revision)
	}
	return worker.WorkerDeploymentVersion{
		DeploymentName: m.Name,
		BuildID:        m.Revision,
	}, nil
}

// ApplyToClientOptions sets the Cloud Run-derived worker identity (see [Metadata.WorkerIdentity])
// on the given client options, unless an identity is already set — a user-provided identity always
// wins. Call it before dialing the Temporal server.
func (m *Metadata) ApplyToClientOptions(o *client.Options) {
	if o.Identity == "" {
		o.Identity = m.WorkerIdentity()
	}
}

// ApplyToWorkerOptions enables Worker Deployment Versioning on the given worker options using the
// Cloud Run deployment version (see [Metadata.DeploymentVersion]), pinning workflows to this
// version by default ([workflow.VersioningBehaviorPinned]). A per-workflow versioning behavior, if
// set, takes precedence. It returns an error, leaving the options unchanged, if the deployment
// version cannot be built.
func (m *Metadata) ApplyToWorkerOptions(o *worker.Options) error {
	v, err := m.DeploymentVersion()
	if err != nil {
		return err
	}
	o.DeploymentOptions = worker.DeploymentOptions{
		UseVersioning:             true,
		Version:                   v,
		DefaultVersioningBehavior: workflow.VersioningBehaviorPinned,
	}
	return nil
}
